SELECT COUNT(DISTINCT a.hadm_id) AS n, AVG(l.value) AS average_troponin_t, STDDEV(l.value) AS standard_deviation_troponin_t, MIN(l.value) AS minimum_troponin_t, MAX(l.value) AS maximum_troponin_t, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY l.value) AS seventy_five_percentile_troponin_t, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY l.value) AS twenty_five_percentile_troponin_t FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN labevents l ON a.hadm_id = l.hadm_id AND l.itemid = 8718088 WHERE p.gender = 'M' AND p.anchor_age = 59 AND p.anchor_year_group BETWEEN 54 AND 64 AND l.value > 0.01 AND l.value_uom = 'ng/mL' AND l.charttime BETWEEN a.admittime AND a.dischtime;